package Tv4.Controller;
import Tv4.View.DiemDanhPage;import MainPage.View.Workspace;import MainPage.Controller.PageTasks;import Model.*;import Service.*;import java.time.*;import java.util.*;import javax.swing.JButton;
public class DiemDanhController {
 private final DiemDanhPage v;private final int b;private boolean binding;private final JButton save;private List<BuoiHocModel> lessons=List.of();private List<DangKyHocModel> regs=List.of();private List<DiemDanhModel> attendance=List.of();private Map<Integer,String> students=Map.of();private record Data(List<LopHocModel> classes,List<BuoiHocModel> lessons,List<DangKyHocModel> regs,List<DiemDanhModel> attendance,List<HocVienModel> students){}
 public DiemDanhController(DiemDanhPage v,int b){this(v,b,"Cơ sở #"+b);}
 public DiemDanhController(DiemDanhPage v,int b,String name){this.v=v;this.b=b;v.title("ĐIỂM DANH — "+name,"Chọn lớp, buổi học; sửa trạng thái và ghi chú rồi xác nhận");v.onClass(()->{if(!binding)chooseClass();});v.onLesson(()->{if(!binding)render();});save=v.action("Xác nhận điểm danh",this::save);save.setEnabled(false);v.action("Tải lại",()->load(true));load(false);}
 private void load(boolean force){save.setEnabled(false);v.status("Đang tải...");PageTasks.run(v,()->{var l=new LopHocService();var s=new BuoiHocService();var r=new DangKyHocService();var d=new DiemDanhService();var h=new HocVienService();return new Data(force?l.reload(b):l.selectAll(b),force?s.reload(b):s.selectAll(b),force?r.reload(b):r.selectAll(b),force?d.reload(b):d.selectAll(b),force?h.reload(b):h.selectAll(b));},a->{lessons=a.lessons;regs=a.regs;attendance=a.attendance;Map<Integer,String> m=new HashMap<>();a.students.forEach(x->m.put(x.getMaHocVien(),x.getHoTen()));students=m;binding=true;v.classes(a.classes.stream().filter(x->"DANG_MO".equals(x.getTrangThai())||lessons.stream().anyMatch(l->l.getMaLop()==x.getMaLop()&&"HOAN_THANH".equals(l.getTrangThai()))).map(x->new DiemDanhPage.Option(x.getMaLop(),x.getTenLop())).toArray(DiemDanhPage.Option[]::new));binding=false;chooseClass();});}
 private void chooseClass(){binding=true;v.lessons(lessons.stream().filter(x->x.getMaLop()==v.classId()&&Set.of("DA_KICH_HOAT","HOAN_THANH").contains(x.getTrangThai())).sorted(Comparator.comparing(BuoiHocModel::getNgayHoc).reversed()).map(x->new DiemDanhPage.Option(x.getMaBuoiHoc(),x.getNgayHoc()+" "+x.getGioBatDau()+" · "+x.getTrangThai())).toArray(DiemDanhPage.Option[]::new));binding=false;render();}
 private void render(){int id=v.lessonId();var l=lessons.stream().filter(x->x.getMaBuoiHoc()==id).findFirst().orElse(null);Map<Integer,Object[]> rows=new LinkedHashMap<>();if(l!=null){for(var r:regs){if(!Objects.equals(r.getMaLop(),l.getMaLop())||r.getNgayBatDau()==null||l.getNgayHoc().isBefore(r.getNgayBatDau())||r.getNgayKetThucThucTe()!=null&&l.getNgayHoc().isAfter(r.getNgayKetThucThucTe())||r.getNgayKetThucThucTe()==null&&r.getNgayKetThucDuKien()!=null&&l.getNgayHoc().isAfter(r.getNgayKetThucDuKien())||Set.of("CHO_XEP_LOP","HUY","TAM_NGHI").contains(r.getTrangThai()))continue;rows.put(r.getMaHocVien(),new Object[]{r.getMaHocVien(),students.get(r.getMaHocVien()),r.getMaDangKy(),"CHINH_THUC","CHUA_DIEM_DANH",false,""});}for(var d:attendance)if(d.getMaBuoiHoc()==id&&!"HUY".equals(d.getTrangThai()))rows.put(d.getMaHocVien(),new Object[]{d.getMaHocVien(),students.get(d.getMaHocVien()),d.getMaDangKy(),d.getLoaiThamGia(),d.getTrangThai(),d.isTinhBuoi(),d.getGhiChu()});}v.attendanceRows(rows.values().toArray(Object[][]::new));save.setEnabled(l!=null&&!rows.isEmpty());v.status(l==null?"Chưa có buổi kích hoạt. Mở Thời khóa biểu để tạo/kích hoạt buổi.":"Buổi #"+id+" | "+rows.size()+" học viên | Tích Tính buổi nếu phù hợp quy định khóa");}
 private void save(){int id=v.lessonId();var inputs=v.inputs();if(id<=0||inputs==null||inputs.length==0)return;for(var i:inputs)if(i.count()&&(i.reg()==null||"CHUA_DIEM_DANH".equals(i.state()))){Workspace.message(v,"Không được tính buổi cho học thử hoặc chưa điểm danh");return;}if(!Workspace.confirm(v,"Xác nhận ghi điểm danh buổi #"+id+"?"))return;PageTasks.actor(v,b,actor->{save.setEnabled(false);PageTasks.run(v,()->{var ds=new DiemDanhService();var ls=new BuoiHocService();var l=ls.getByMaBuoiHoc(b,id);PageTasks.require(l!=null&&Set.of("DA_KICH_HOAT","HOAN_THANH").contains(l.getTrangThai()),"Buổi không hợp lệ");var existing=ds.reload(b);int ok=0;String error="";for(var i:inputs){try{var d=existing.stream().filter(x->x.getMaBuoiHoc()==id&&x.getMaHocVien()==i.hv()).findFirst().orElse(null);boolean fresh=d==null;if(fresh){d=new DiemDanhModel();d.setMaHocVien(i.hv());d.setMaBuoiHoc(id);d.setMaDangKy(i.reg());d.setLoaiThamGia(i.kind());}PageTasks.require(!"HUY".equals(d.getTrangThai()),"Bản ghi đã hủy");d.setTrangThai(i.state());d.setTinhBuoi(i.count());d.setGhiChu(i.note());d.setMaNguoiCapNhat(actor);d.setNgayCapNhat(LocalDateTime.now(ZoneOffset.UTC));PageTasks.require(fresh?ds.insert(b,d):ds.update(b,d),"Lỗi ghi học viên #"+i.hv());ok++;}catch(Exception e){error=e.getMessage();break;}}if(ok==inputs.length&&Arrays.stream(inputs).noneMatch(i->"CHUA_DIEM_DANH".equals(i.state()))&&!"HOAN_THANH".equals(l.getTrangThai())){l.setTrangThai("HOAN_THANH");if(!ls.update(b,l))error="Điểm danh đã lưu, chưa cập nhật trạng thái buổi";}return "Đã ghi "+ok+" / "+inputs.length+" dòng"+(error.isEmpty()?"":". WARNING — "+error+". Kiểm tra trước khi thử lại.");},msg->{Workspace.message(v,msg);load(false);});});}
}
